'use strict';
const test=require('node:test');
const assert=require('node:assert/strict');
const {freezeGraph}=require('../freeze.cjs');
test('deep shared cyclic values and special properties',()=>{
  const symbol=Symbol('settings'), shared={count:1}, root={items:[shared],other:shared};
  root.self=root; root[symbol]={enabled:true};
  Object.defineProperty(root,'hidden',{value:{code:7},enumerable:false});
  let reads=0;
  Object.defineProperty(root,'computed',{get(){reads++; return {temporary:true};}});
  assert.equal(freezeGraph(root),root);
  for(const value of [root,root.items,shared,root[symbol],root.hidden]) assert.equal(Object.isFrozen(value),true);
  assert.equal(reads,0);
  assert.throws(()=>{shared.count=2;},TypeError);
  assert.throws(()=>{root.items.push({});},TypeError);
});
test('primitive roots',()=>{
  for(const value of [null,undefined,7,'ok',true]) assert.equal(freezeGraph(value),value);
  const fn=()=>1;
  assert.equal(freezeGraph(fn),fn);
  assert.equal(Object.isFrozen(fn),false);
});

